using Microsoft.EntityFrameworkCore; using MiniStore.Domain.Entities; using MiniStore.Domain.Interfaces.Accounting; using MiniStore.Infrastructure.Persistence;
namespace MiniStore.Infrastructure.Repositories.Accounting;
public sealed class BankStatementRepository(AppDbContext context) : IBankStatementRepository { public Task<List<BankAccount>> GetAccountsAsync()=>context.BankAccounts.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(); public Task<BankAccount?> GetAccountAsync(int id)=>context.BankAccounts.FirstOrDefaultAsync(x=>x.Id==id); public Task<bool> ImportExistsAsync(int id,string hash)=>context.BankStatementImports.AnyAsync(x=>x.BankAccountId==id&&x.ContentHash==hash); public Task<bool> LineExistsAsync(int id,string hash)=>context.BankStatementImports.Where(x=>x.BankAccountId==id).SelectMany(x=>x.Lines).AnyAsync(x=>x.Fingerprint==hash); public Task AddAccountAsync(BankAccount x)=>context.BankAccounts.AddAsync(x).AsTask(); public Task AddImportAsync(BankStatementImport x)=>context.BankStatementImports.AddAsync(x).AsTask(); public Task<List<BankStatementImport>> GetImportsAsync()=>context.BankStatementImports.AsNoTracking().Include(x=>x.Lines).OrderByDescending(x=>x.ImportedAtUtc).ToListAsync(); public Task SaveChangesAsync()=>context.SaveChangesAsync(); }
